<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue';import {account,plex} from './plex-client';import {getLearning,putLearning} from './learning-store';import {registerLearningFlush} from './learning-flush';import {pendingQa,readingMaterial} from './reading-context';
const props=defineProps<{section:string}>();
interface Comment {id:number;parent_id:number|null;author:string;content:string;quote?:{text:string;block_id:string};ai_assisted:boolean;deleted:boolean;can_delete:boolean;likes:number;liked:boolean;created_at:string;replies?:Comment[];reply_count?:number}
const items=ref<Comment[]>([]),page=ref(1),more=ref(false),text=ref(''),parent=ref<number|null>(null),error=ref(''),loading=ref(false),sending=ref(false),ai=ref(false),quote=ref<{text:string;block_id:string}>(),notice=ref('');
let disposed=false,requestId=crypto.randomUUID(),signature='',timer:ReturnType<typeof setTimeout>|undefined;const abort=new AbortController();
const draftKey='qa-draft:'+props.section;
async function save(){await putLearning(draftKey,{text:text.value,parent:parent.value,ai:ai.value,quote:quote.value,requestId,signature});}
watch([text,parent,ai,quote],()=>{clearTimeout(timer);timer=setTimeout(()=>void save().catch(()=>error.value='问答草稿保存失败，请复制文字后重试。'),500);});
const unregister=registerLearningFlush(save);
async function load(){if(!account())return;loading.value=true;error.value='';try{const data=await plex<{items:Comment[];has_more:boolean}>(`/ebook/qa?section=${encodeURIComponent(props.section)}&page=${page.value}`,undefined,'GET',abort.signal);if(disposed)return;items.value=data.items;repliesPage.value={};more.value=data.has_more;}catch(e){if(!disposed)error.value='问答未加载：'+String(e);}finally{loading.value=false;}}
async function send(){if(sending.value||!text.value.trim()||text.value.length>2000)return;const body={section:props.section,content:text.value,parent_id:parent.value,quote:quote.value,ai_assisted:ai.value};const sig=JSON.stringify(body);if(signature!==sig){signature=sig;requestId=crypto.randomUUID();}sending.value=true;error.value='';try{await save();await plex('/ebook/qa',{...body,request_id:requestId},'POST',abort.signal);if(disposed)return;text.value='';parent.value=null;quote.value=undefined;ai.value=false;signature='';notice.value='已发布到共享问答。';await save();await load();}catch(e){if(!disposed)error.value='发布未确认，输入已保留；重试不会重复发布：'+String(e);}finally{sending.value=false;}}
async function action(row:Comment,kind:'like'|'delete'){try{await plex(`/ebook/qa/${row.id}${kind==='like'?'/like':''}`,undefined,kind==='like'?'POST':'DELETE',abort.signal);await load();}catch(e){error.value=String(e);}}
const repliesPage=ref<Record<number,number>>({});async function replies(row:Comment){const next=(repliesPage.value[row.id]||1)+1;try{const data=await plex<{items:Comment[]}>(`/ebook/qa?section=${encodeURIComponent(props.section)}&parent_id=${row.id}&page=${next}`,undefined,'GET',abort.signal);row.replies=[...(row.replies||[]),...data.items];repliesPage.value[row.id]=next;}catch(e){error.value=String(e);}}
function login(){window.dispatchEvent(new Event('plex-pet-login'));}
function addQuote(){const source=readingMaterial.value;if(source?.section_id===props.section)quote.value={text:source.text.slice(0,1000),block_id:source.block_id};}
onMounted(async()=>{const saved=await getLearning<any>(draftKey,null);if(disposed)return;if(saved){text.value=saved.text||'';parent.value=saved.parent||null;ai.value=!!saved.ai;quote.value=saved.quote;requestId=saved.requestId||requestId;signature=saved.signature||'';}if(pendingQa.value?.section===props.section){text.value=pendingQa.value.text;if(text.value.length>2000)error.value='内容超过 2000 字，请精简后发布。';ai.value=pendingQa.value.ai;pendingQa.value=null;}await load();});onBeforeUnmount(()=>{disposed=true;abort.abort();clearTimeout(timer);void save().catch(()=>{});unregister();});
</script>
<template><section class="starship-workbench ebook-qa"><h3>本节 QA · 共同讨论</h3><p>所有教材登录用户共享；个人小E答复不会自动发布。</p><button v-if="!account()" @click="login">登录 PLEX 后参与</button><template v-else><button :disabled="loading" @click="load">刷新问答</button><p v-if="loading">正在加载…</p><p v-else-if="!items.length&&!error">还没有问题，分享你的第一个疑惑。</p><article v-for="row in items" :key="row.id" class="qa-thread"><small>{{row.author}} · {{row.created_at}} {{row.ai_assisted?'· AI 辅助内容':''}}</small><p class="qa-text">{{row.content}}</p><blockquote v-if="row.quote">{{row.quote.text}} <a :href="'/read/'+section+'#'+encodeURIComponent(row.quote.block_id)+'@0'">返回引用原文</a></blockquote><button :disabled="row.deleted" @click="action(row,'like')">{{row.liked?'取消赞':'赞'}} {{row.likes}}</button><button @click="parent=row.id">回复</button><button v-if="row.can_delete&&!row.deleted" @click="action(row,'delete')">删除我的内容／管理删除</button><div v-for="reply in row.replies" :key="reply.id" class="qa-reply"><small>{{reply.author}}{{reply.ai_assisted?' · AI 辅助内容':''}}</small><p class="qa-text">{{reply.content}}</p><button :disabled="reply.deleted" @click="action(reply,'like')">{{reply.liked?'取消赞':'赞'}} {{reply.likes}}</button><button v-if="reply.can_delete&&!reply.deleted" @click="action(reply,'delete')">删除回复</button></div><button v-if="(row.reply_count||0)>(row.replies?.length||0)" @click="replies(row)">加载更多回复</button></article><div><button :disabled="page===1||loading" @click="page--;load()">上一页讨论</button><span>第 {{page}} 页</span><button :disabled="!more||loading" @click="page++;load()">下一页讨论</button></div><p v-if="parent">回复问题 #{{parent}} <button @click="parent=null">取消回复</button></p><label>提问或回复<textarea v-model="text" maxlength="2000" rows="5" :disabled="sending" /></label><label><input v-model="ai" type="checkbox" :disabled="sending"/>此内容使用了 AI 辅助</label><button v-if="readingMaterial?.section_id===section" @click="addQuote">附上框选文字引用</button><blockquote v-if="quote">{{quote.text}}<button @click="quote=undefined">移除引用</button></blockquote><p>发布后其他登录读者可见，请确认内容。</p><button :disabled="sending||!text.trim()||text.length>2000" @click="send">{{sending?'正在发布':'确认发布到共享问答'}}</button></template><p v-if="error" role="alert">{{error}}</p><p role="status">{{notice}}</p></section></template>
<style>.ebook-qa textarea{display:block;width:100%;background:#101d30;color:#f5f9ff;padding:12px;border:1px solid #718aaa}.qa-thread{border-top:1px solid #547082;padding:20px 0}.qa-reply{margin:12px 0 0 20px;padding:12px;border-left:2px solid #55bfcf}.qa-text{white-space:pre-wrap;overflow-wrap:anywhere}.ebook-qa a{color:#92e6ff}</style>
